"""Alien Dictionary — topological sort of the letter precedence graph.

Adjacent words give one constraint each: the first differing character. A prefix
that comes after its own extension ("abc" before "ab") is invalid outright.
Ties are broken alphabetically with a heap so the answer is deterministic.

Time: O(total characters + V + E)   Space: O(V + E)
"""
import heapq
from collections import defaultdict
from typing import List


class Solution:
    def alienOrder(self, words: List[str]) -> str:
        graph = defaultdict(set)
        indegree = {ch: 0 for word in words for ch in word}

        for first, second in zip(words, words[1:]):
            for a, b in zip(first, second):
                if a != b:
                    if b not in graph[a]:
                        graph[a].add(b)
                        indegree[b] += 1
                    break
            else:
                if len(first) > len(second):
                    return ""

        heap = [ch for ch, deg in indegree.items() if deg == 0]
        heapq.heapify(heap)
        out = []
        while heap:
            ch = heapq.heappop(heap)
            out.append(ch)
            for nxt in sorted(graph[ch]):
                indegree[nxt] -= 1
                if indegree[nxt] == 0:
                    heapq.heappush(heap, nxt)
        return "".join(out) if len(out) == len(indegree) else ""
